-- TV课截止当周到课率

select subject_id,semester_type_cd,stage_name,start_class_dt,week_idx
	,count(distinct user_id) as user_cnt
	,count(distinct if(is_watched = 1,user_id,null)) as watch_cnt
from
	(select subject_id,stage_name,semester_type_cd,start_class_dt,um.user_id,um.week_idx
        ,max(if(is_watched+is_cur_week_playback > 0, 1, 0)) as is_watched
    from
        (select subject_id,stage_name,semester_type_cd,start_class_dt,semester_id,userid AS user_id,week_idx,mission_id
                ,edition_id,template_id as mission_template_id
        from dw_dwd.dwd_eng_course_user_mission_da 
        where dt = date_sub(current_date,1)
            and mission_type_cd = '4'
            and is_test = '0'
            and {{subject_id}}
            and {{stage_name}}
            and {{start_class_dt}}
            and {{semester_type_cd}}
        group by subject_id,stage_name,semester_type_cd,start_class_dt,semester_id,userid,week_idx,mission_id,edition_id,template_id
        ) um   -- D5 TV课mission
    left join 
        (select user_id,mission_id
            ,sum(is_watched) as is_watched -- 是否观看直播
            ,sum(is_cur_week_playback) as is_cur_week_playback -- 是否回放
        from dw_dwd.dwd_eng_course_user_watch_tv_da
        where dt = date_sub(current_date,1)
            and {{subject_id}}
            and {{stage_name}}
            and {{regexp_replace(split(period_type,'-')[1],'\\/','\\-') as start_class_dt}}
            and {{semester_type_cd}}
        group by user_id,mission_id
        ) tv_info
        on um.user_id = tv_info.user_id and um.mission_id=tv_info.mission_id
    group by subject_id,stage_name,semester_type_cd,start_class_dt,um.user_id,um.week_idx
    ) a
group by subject_id,semester_type_cd,stage_name,start_class_dt,week_idx
